/* @lc app=leetcode id=3576 lang=kotlin */ class Solution { fun cost(nums: IntArray, t: Int): Int = nums.indices.fold(false to 0) { (fl, ops), i -> (if (fl) -nums[i] else nums[i]).let { cur -> if (i == nums.size - 1) (if (cur == t) false to ops else false to 1_000_000_000) else if (cur != t) true to ops + 1 else false to ops } }.second fun canMakeEqual(nums: IntArray, k: Int): Boolean = minOf(cost(nums, 1), cost(nums, -1)) <= k }